import{_ as t,o as s,c as o,a2 as a}from"./chunks/framework.YiAtXB4p.js";const u=JSON.parse('{"title":"ESI.ts Documentation Guide","description":"","frontmatter":{"title":"ESI.ts Documentation Guide","sourceFile":"guides/DOCUMENTATION.md"},"headers":[],"relativePath":"guide/documentation.md","filePath":"guide/documentation.md"}'),d={name:"guide/documentation.md"};function i(n,e,c,r,h,l){return s(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="esits-documentation-guide" tabindex="-1">ESI.ts Documentation Guide <a class="header-anchor" href="#esits-documentation-guide" aria-label="Permalink to &quot;ESI.ts Documentation Guide&quot;">​</a></h1><p><strong>Implements:</strong> <code>DOC-02</code> · <code>DOC-03</code> · <code>DOC-04</code> · <code>DOC-05</code> · <code>DOC-06</code> — see <a href="./charter">CHARTER.md</a> Part 7. <code>DOC-01</code> is Gap today and lands with the 11.0 docs rewrite (ROADMAP Phase 7).</p><p>Where the documentation lives, how the site and the API reference are built and published, how examples in the guides are kept compiling, and what a pull request that adds a public export owes the documentation. The code is the fact: where a page and the code disagree, fix the page.</p><h2 id="where-documentation-lives" tabindex="-1">Where documentation lives <a class="header-anchor" href="#where-documentation-lives" aria-label="Permalink to &quot;Where documentation lives&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What</th><th>Where</th><th>Canonical for</th></tr></thead><tbody><tr><td>Orientation, install, first calls</td><td><code>README.md</code></td><td>Nothing it can link to instead; it points at a guide for depth</td></tr><tr><td>Engineering requirements and status</td><td><a href="./charter">CHARTER.md</a></td><td>Every <code>ARCH</code>, <code>DES</code>, <code>TEST</code>, <code>GATE</code>, <code>SEC</code>, <code>DOC</code>, <code>REL</code> and <code>PROC</code> requirement</td></tr><tr><td>The 11.0 plan</td><td><a href="./roadmap">ROADMAP.md</a></td><td>Phase schedule, definitions of done, the release gate</td></tr><tr><td>One topic per guide</td><td><code>guides/*.md</code></td><td>The topic in its title; each opens with an <code>Implements:</code> line naming the requirements it serves</td></tr><tr><td>API reference</td><td>TypeDoc from the TSDoc in <code>src/</code></td><td>Signatures, parameters, JSDoc</td></tr><tr><td>Documentation site</td><td><code>docs-site/</code> (VitePress)</td><td>Nothing: its guide and example pages are generated from the files above</td></tr><tr><td>Runnable programs</td><td><code>examples/*.ts</code></td><td>Whole programs; type-checked by <code>npm run typecheck:examples</code> in <code>ci-fast.yml</code></td></tr><tr><td>Static Data Export</td><td><code>guides/SDE.md</code>, <code>guides/sde/*.md</code></td><td>The <code>./sde</code> and <code>./sde/memory</code> sub-paths; <code>src/sde/README.md</code> is a pointer to them</td></tr><tr><td>Test specification</td><td><code>tests/bdd/features/**/*.feature</code></td><td>Behaviour, as EARS requirements with Gherkin scenarios</td></tr><tr><td>Public API surface</td><td><code>etc/esi.ts.api.md</code></td><td>Every exported shape, regenerated by <code>npm run api-report</code></td></tr><tr><td>Agent instructions</td><td><code>CLAUDE.md</code>, <code>AGENTS.md</code></td><td>How an agent works in the repository; the SemVer section is mirrored and checked</td></tr><tr><td>Changelog</td><td><code>CHANGELOG.md</code></td><td>Written by release-please from conventional commits</td></tr></tbody></table><h2 id="the-documentation-site" tabindex="-1">The documentation site <a class="header-anchor" href="#the-documentation-site" aria-label="Permalink to &quot;The documentation site&quot;">​</a></h2><p><a href="https://lgriffin.github.io/ESI.ts/" target="_blank" rel="noreferrer">https://lgriffin.github.io/ESI.ts/</a> is built from the repository, so it cannot say anything the guides and examples do not (<code>DOC-03</code>). Only <code>docs-site/index.md</code> (the home page), <code>docs-site/.vitepress/config.ts</code> and the theme are written by hand; everything else is generated at build time and git-ignored.</p><table tabindex="0"><thead><tr><th>Route</th><th>Built from</th><th>How</th></tr></thead><tbody><tr><td><code>/guide/</code></td><td><code>README.md</code> and every <code>guides/*.md</code></td><td><code>scripts/docs/sync-docs.ts</code> copies each file. A link to another guide becomes a link to its page, a link to any other repository file becomes a GitHub URL, and an image is copied beside the page. The sidebar sections are <code>GUIDE_SECTIONS</code> in <code>scripts/docs/sync-docs-core.ts</code>; a guide not listed there is still published, in the last section</td></tr><tr><td><code>/examples/</code></td><td>every <code>examples/*.ts</code></td><td>One page per example from its header comment (title, description, <code>Setup:</code>, <code>@nightly</code> tier) and its source, imports rewritten to the package sub-paths a consumer uses (<code>IMPORT_MAP</code> in <code>scripts/docs/examples-showcase-core.ts</code>), plus an index grouped by category</td></tr><tr><td><code>/api/</code></td><td>the TSDoc in <code>src/</code></td><td>TypeDoc (next section), copied as static files</td></tr></tbody></table><p>The version in the navigation bar is read from <code>package.json</code> when the site builds. Edit the guide or the example, never a generated page; each generated page&#39;s &quot;Edit this page&quot; link opens its source. A new example needs a title line and an <code>@nightly</code> tag, which it already needs for the nightly run, and an import of a <code>../src</code> path <code>IMPORT_MAP</code> does not know fails the build until it is mapped.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs-site</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # once: the site&#39;s own dependencies (VitePress)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:site</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # TypeDoc, docs:sync, then vitepress build into docs-site/.vitepress/dist/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:site:preview</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # serve the built site at http://localhost:4173/ESI.ts/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:site:dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # docs:sync, then VitePress with hot reload (run npm run docs first for /api/)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:sync</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # regenerate the guide and example pages only</span></span></code></pre></div><p>Where it is built:</p><table tabindex="0"><thead><tr><th>Where</th><th>What happens</th></tr></thead><tbody><tr><td><code>ci.yml</code> <code>documentation</code> job</td><td>Runs <code>npm run docs:site</code> and <code>validate:versions -- --site</code> on every pull request, and uploads the built site as the <code>documentation</code> artifact for 30 days</td></tr><tr><td><code>release.yml</code> <code>deploy-docs</code></td><td>Calls <code>docs-site.yml</code> after <code>validate-release</code> passes on the release&#39;s tag</td></tr><tr><td><code>docs-site.yml</code> (also <code>workflow_dispatch</code>)</td><td>Builds the site, checks its version, and publishes <code>docs-site/.vitepress/dist</code> to the <code>gh-pages</code> branch. Dispatch it on master to publish between releases</td></tr></tbody></table><p>VitePress fails the build on a link to a page that does not exist. Links that become GitHub URLs are checked by <code>tests/tdd/scripts/sync-docs.test.ts</code>, which fails when a guide links to a repository file that is not there. GitHub Pages must serve the <code>gh-pages</code> branch (repository Settings, Pages, &quot;Deploy from a branch&quot;); that setting is the maintainer&#39;s.</p><h2 id="api-reference-typedoc" tabindex="-1">API reference (TypeDoc) <a class="header-anchor" href="#api-reference-typedoc" aria-label="Permalink to &quot;API reference (TypeDoc)&quot;">​</a></h2><p><code>typedoc.json</code> expands every module under <code>src/</code> and writes HTML to <code>docs-site/public/api/</code>, which <code>.gitignore</code> excludes. No committed file lives under that directory, and <code>npm run clean</code> and <code>npm run clean:docs</code> delete only it (<code>DOC-02</code>).</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # Generate into docs-site/public/api/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:watch</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # Regenerate on change</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:serve</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # Serve docs-site/public/api at http://localhost:8080</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean:docs</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # Delete docs-site/public/api/</span></span></code></pre></div><p>Where it is built:</p><table tabindex="0"><thead><tr><th>Where</th><th>What happens</th></tr></thead><tbody><tr><td><code>ci.yml</code> <code>documentation</code> job</td><td>Runs it as part of <code>npm run docs:site</code> on every pull request</td></tr><tr><td><code>release.yml</code> <code>validate-release</code></td><td>Runs <code>npm run docs</code>, so a TypeDoc failure blocks the release</td></tr><tr><td><code>docs-site.yml</code></td><td>Publishes it under <code>/api/</code> with the site</td></tr><tr><td><code>release.yml</code> <code>create-assets</code></td><td>Attaches <code>docs.tar.gz</code> to the GitHub release, listed in <code>checksums.txt</code> with the tarball and SBOM</td></tr></tbody></table><p>What TypeDoc shows is what the TSDoc says. The public classes it documents are the construction surfaces (<code>EsiClient</code>, <code>EsiClientBuilder</code>, <code>CustomEsiClient</code>, <code>EsiApiFactory</code>), the 39 domain clients, the auth classes (<code>EveSsoClient</code>, <code>EsiTokenManager</code>, the token stores), the middleware and its interfaces (<code>ICache</code>, <code>IRateLimiter</code>, <code>ICircuitBreaker</code>, <code>IRetryStrategy</code>, <code>IDeduplicator</code>, <code>ILogger</code>), the error classes, and the response types: 36 domain type files in <code>src/types/</code> plus <code>common.ts</code>, <code>branded.ts</code> and <code>api-responses.ts</code>. Because <code>entryPoints</code> is all of <code>src/</code>, TypeDoc also renders modules the package does not export, including <code>src/core/ports/</code>, <code>src/adapters/</code> and <code>src/generated/operations.generated.ts</code>. The <code>exports</code> map in <code>package.json</code> and <code>etc/esi.ts.api.md</code> decide what is public, not the reference.</p><h2 id="guide-conventions" tabindex="-1">Guide conventions <a class="header-anchor" href="#guide-conventions" aria-label="Permalink to &quot;Guide conventions&quot;">​</a></h2><p>Every guide follows the same shape, so a reader can move between them without relearning the layout (<code>DOC-05</code>).</p><ul><li><strong>First line after the title: <code>**Implements:**</code></strong> with the requirement identifiers the guide serves and a link to <a href="./charter">CHARTER.md</a>. Seven guides still lack one (CHARTER DOC-05 lists them); add it when you next edit one.</li><li><strong>Reachable from the README</strong> within one link.</li><li><strong>Plain declarative sentences.</strong> Say what the code does and name the file, script or CI job that proves it. A claim with no mechanism behind it is a requirement with status Gap, and belongs in the CHARTER as one.</li><li><strong>State the gap.</strong> Where the code falls short of the charter, say so in the guide and cite the requirement or issue. Do not soften it.</li><li><strong>Counts are generated.</strong> A count of something in the source (clients, routes, operations, requirements, scenarios, examples, test files) is written between markers, <code>&lt;!-- metric:clients --&gt;39&lt;!-- /metric --&gt;</code>, never typed as a bare number. <code>npm run docs:metrics</code> computes every metric into <code>etc/doc-metrics.json</code> and rewrites the marked numbers; <code>validate:versions</code> fails when one is stale. The metric names are <code>METRIC_NAMES</code> in <code>scripts/docs/doc-metrics-core.ts</code>, and a marker must not start a line, because Markdown reads a line that opens with a comment as HTML. A count only a test run can measure stays prose with the date it was measured (<code>DOC-04</code>).</li><li><strong>No duplication.</strong> When a topic has a canonical guide, link to it and summarise in one sentence (<code>DOC-01</code>).</li></ul><h2 id="when-a-public-export-is-added" tabindex="-1">When a public export is added <a class="header-anchor" href="#when-a-public-export-is-added" aria-label="Permalink to &quot;When a public export is added&quot;">​</a></h2><p><code>DOC-06</code> asks that a pull request adding a public export carries its documentation with it:</p><ol><li><strong>JSDoc</strong> on the export. TypeDoc and the API report both read it.</li><li><strong>A guide section</strong> in the canonical guide for the topic, with a type-checked example.</li><li><strong>An example</strong> under <code>examples/</code> when the export is user-facing.</li><li><strong>The API report</strong>: <code>npm run build &amp;&amp; npm run api-report</code>, and commit <code>etc/esi.ts.api.md</code>. The <code>api-surface</code> job fails when it is stale.</li></ol><p>Only part of this is checked. <code>npm run test:export-coverage -- --ci</code> fails a pull request that adds an export no test references, and the API report diff makes the addition visible to the reviewer. There is no pull request template checklist yet, so items 1 to 3 are review items (<code>DOC-06</code> is Gap).</p><h2 id="documentation-examples-are-checked" tabindex="-1">Documentation examples are checked <a class="header-anchor" href="#documentation-examples-are-checked" aria-label="Permalink to &quot;Documentation examples are checked&quot;">​</a></h2><p>A README example that does not compile costs more trust than a bug. <code>npm run test:docs-examples</code> finds every fenced <code>ts</code> or <code>typescript</code> block in <code>README.md</code>, <code>guides/*.md</code>, <code>guides/sde/*.md</code> and <code>src/sde/README.md</code>, and checks it against the packed package, the way a reader who copies it sees it:</p><ol><li>Builds and packs the library as the consumer contract does, and installs the tarball into a scratch consumer outside the repository.</li><li>Writes each block to its own ES module next to a shared prelude, and type-checks all of them with <code>strict</code> under <code>moduleResolution: nodenext</code> and <code>bundler</code>. An import of a sub-path the package&#39;s <code>exports</code> map does not list fails here.</li><li>Runs each block marked <code>runnable</code> with node, with <code>fetch</code> replaced by a stub.</li></ol><p>CI runs it in the <code>doc-examples</code> job, inside <code>ci-success</code>. <code>npm test</code> checks the annotations and the baseline without packing.</p><h3 id="fragments-and-the-prelude" tabindex="-1">Fragments and the prelude <a class="header-anchor" href="#fragments-and-the-prelude" aria-label="Permalink to &quot;Fragments and the prelude&quot;">​</a></h3><p>Most blocks are fragments: they use a <code>client</code> built in an earlier block, or a <code>characterId</code> the reader supplies. <a href="https://github.com/lgriffin/ESI.ts/blob/master/tests/doc-examples/prelude.d.ts" target="_blank" rel="noreferrer"><code>tests/doc-examples/prelude.d.ts</code></a> declares those names as typed globals, so a fragment type-checks as written. A block that declares or imports a name itself shadows the global. When a new fragment needs a name the prelude lacks, add it there with the type a reader would have; do not type it <code>any</code>.</p><h3 id="annotations" tabindex="-1">Annotations <a class="header-anchor" href="#annotations" aria-label="Permalink to &quot;Annotations&quot;">​</a></h3><p>A block is type-checked unless it says otherwise. Two annotations exist, and anything else is an error, so a typo cannot switch a check off:</p><table tabindex="0"><thead><tr><th>Annotation</th><th>Where</th><th>Effect</th></tr></thead><tbody><tr><td><code>runnable</code></td><td>The fence (<code>\`\`\`ts runnable</code>) or a comment</td><td>Type-checked, then run against the stub transport in <a href="../tests/doc-examples/stub-fetch.mjs"><code>tests/doc-examples/stub-fetch.mjs</code></a>. The block must build everything it uses: prelude names do not exist at runtime</td></tr><tr><td><code>&lt;!-- doc-example: no-check &lt;reason&gt; --&gt;</code></td><td>A comment on the line above the fence (blank lines between are fine)</td><td>Not checked. The reason is required</td></tr></tbody></table><p>Use <code>no-check</code> for blocks that are not consumer code: method signature listings, fragments of a class body, and contributor examples that import from <code>src/</code>. Do not use it to silence an example that is wrong; fix the example.</p><h3 id="known-broken-examples" tabindex="-1">Known-broken examples <a class="header-anchor" href="#known-broken-examples" aria-label="Permalink to &quot;Known-broken examples&quot;">​</a></h3><p>When an example exposes a real mismatch that cannot be fixed in the docs alone, mark it <code>no-check</code> with a reason that names the bead tracking it, for example <code>&lt;!-- doc-example: no-check esi-abc.1 getFoo was removed; decide the replacement --&gt;</code>, and list its key in <a href="https://github.com/lgriffin/ESI.ts/blob/master/scripts/docs/doc-examples-baseline.json" target="_blank" rel="noreferrer"><code>scripts/docs/doc-examples-baseline.json</code></a>. The key is the file, the nearest heading, and the block&#39;s position under that heading: <code>README.md#Quick Start [1]</code>.</p><p>The baseline only shrinks. The run fails when a <code>no-check</code> names a bead but is not listed, when a listed block no longer exists or no longer names a bead (remove the entry once the example is fixed), and when an entry is not on <code>origin/master</code> already. Without <code>origin/master</code> to compare with, the run fails closed; CI fetches it first.</p><h3 id="negative-fixtures" tabindex="-1">Negative fixtures <a class="header-anchor" href="#negative-fixtures" aria-label="Permalink to &quot;Negative fixtures&quot;">​</a></h3><p><code>tests/tdd/doc-examples/fixtures/</code> holds a compliant file and four that must be rejected: a block that does not parse (tsc reports no type errors while any file has a syntax error, so the checker drops such blocks and checks the rest again), a block calling a method that does not exist, an import of <code>@lgriffin/esi.ts/dist/errors</code> (present in the tarball but not exported), and a <code>no-check</code> without a reason. <code>tests/tdd/doc-examples/doc-examples.test.ts</code> puts them through the checker against a small stub package, and <code>npm run test:docs-examples</code> puts them through again against the packed library. If a fixture stops being rejected, both fail.</p><h2 id="what-changes-in-110" tabindex="-1">What changes in 11.0 <a class="header-anchor" href="#what-changes-in-110" aria-label="Permalink to &quot;What changes in 11.0&quot;">​</a></h2><p>ROADMAP Phase 7 rewrites the documentation against the new client. The site build (<code>DOC-03</code>), the generated counts (<code>DOC-04</code>) and the single testing guide (<code>DOC-01</code>: root <code>TESTING.md</code> and the former <code>guides/MUTATION-TESTING.md</code> folded into <code>guides/TESTING.md</code>, <a href="https://github.com/lgriffin/ESI.ts/issues/273" target="_blank" rel="noreferrer">#273</a>) have landed; nothing else in this list exists yet:</p><ul><li>The README becomes an orientation page written against <code>createEsi</code> and <code>esi.as(identity)</code>, every snippet checked by <code>test:docs-examples</code>. <code>guides/MULTI-CHARACTER.md</code> arrived with ROADMAP Phase 2 PR 11.</li><li>The Beads blocks in <code>AGENTS.md</code> and <code>CLAUDE.md</code> become pointers (<a href="https://github.com/lgriffin/ESI.ts/issues/276" target="_blank" rel="noreferrer">#276</a>).</li></ul>`,44)])])}const m=t(d,[["render",i]]);export{u as __pageData,m as default};
